+#[test]
+fn hashline_count_salt_rejects_a_stale_duplicate_and_the_retry_lands() {
+    // The issue's shape: a read shows two copies of `}` (and of `if u.banned`).
+    // Between turns a hook adds a block above the target holding a third copy.
+    // Under salt = "count" every copy's hash changes, so the stale hash-only
+    // anchor is not found; the fresh anchor from the rejection lands.
+    let env = Env::new(
+        "hashline-count",
+        json!({ "steps": [
+            { "call": "read", "args": { "path": "guard.py" } },
+            { "call": "shell", "args": { "command": "awk 'NR==2{print \"    if u.admin:\"; print \"        return None\"} {print}' guard.py > guard.new && mv guard.new guard.py" } },
+            { "call": "edit", "args": { "path": "guard.py", "edits": [ { "op": "set", "anchor": "gg", "text": "    return False" } ] } },
+            { "call": "edit", "args": { "path": "guard.py", "edits": [ { "op": "set", "anchor": "yf", "text": "    return False" } ] } },
+            { "text": "done" }
+        ] }),
+    );
+    env.config("[tools]\neditor = \"hashline\"\n\n[tools.hashline]\nanchor = \"hash\"\nsalt = \"count\"\n");
+    std::fs::write(
+        env.work.join("guard.py"),
+        "def f(u):\n    if u.banned:\n        return None\n    audit(u)\n    return None\n",
+    )
+    .unwrap();
+    let out = env.run(&["run", "--json", "--no-learn", "make the banned branch return False"]);
+    assert!(out.status.success(), "{}", text(&out));
+    let reqs = env.requests();
+    // The read's anchors are the count-salted ones: `return None` rank 1 of 2.
+    assert_eq!(
+        last_tool_result(&reqs[1]),
+        "ep|def f(u):\nzq|    if u.banned:\npl|        return None\nsz|    audit(u)\ngg|    return None\n"
+    );
+    // After the hook inserted a third copy above, the stale anchor is gone.
+    let rejected = last_tool_result(&reqs[3]);
+    assert!(rejected.starts_with("Error: REJECTED: 1 of 1 edit(s)"), "{rejected}");
+    assert!(rejected.contains("ANCHOR_NOT_FOUND"), "{rejected}");
+    assert!(rejected.contains("no line has hash \"gg\" now"), "{rejected}");
+    // Hash mode has no window; the message tells the model to read again, and
+    // the retry below uses the fresh anchor for the final copy.
+    assert!(rejected.contains("read the file again"), "{rejected}");
+    assert!(!rejected.contains("current content"), "{rejected}");
+    let applied = last_tool_result(&reqs[4]);
+    assert!(applied.starts_with("ok: applied 1 edit(s) to guard.py: replaced line 7"), "{applied}");
+    assert_eq!(
+        std::fs::read_to_string(env.work.join("guard.py")).unwrap(),
+        "def f(u):\n    if u.admin:\n        return None\n    if u.banned:\n        return None\n    audit(u)\n    return False\n"
+    );
+    let events: Vec<Value> =
+        String::from_utf8_lossy(&out.stdout).lines().filter_map(|l| serde_json::from_str(l).ok()).collect();
+    let edits: Vec<&Value> = events.iter().filter(|e| e["event"] == "tool_end" && e["name"] == "edit").collect();
+    assert_eq!((edits[0]["ok"].clone(), edits[0]["code"].clone()), (json!(false), json!("ANCHOR_NOT_FOUND")));
+    assert_eq!((edits[1]["ok"].clone(), edits[1]["data"]["status"].clone()), (json!(true), json!("applied")));
+    let manifest = events.iter().find(|e| e["event"] == "manifest").expect("manifest event");
+    assert_eq!(manifest["hashline"]["salt"], "count");
+    assert_eq!(manifest["hashline"]["anchor"], "hash");
+    // `construct manifest` prints the same knob.
+    let shown = env.run(&["manifest"]);
+    assert!(shown.status.success(), "{}", text(&shown));
+    let m: Value = serde_json::from_slice(&shown.stdout).unwrap();
+    assert_eq!(m["hashline"]["salt"], "count");
+    assert_eq!(m["hashline"]["anchor"], "hash");
+    // The default salt stays "rank", with no config file.
+    let plain = Env::new("hashline-default", json!({ "steps": [ { "text": "ok" } ] }));
+    let p_out = plain.run_with(&[("CONSTRUCT_TOOLS_EDITOR", "hashline")], &["manifest"]);
+    assert!(p_out.status.success(), "{}", text(&p_out));
+    let p: Value = serde_json::from_slice(&p_out.stdout).unwrap();
+    assert_eq!(p["hashline"]["salt"], "rank");
+    assert_eq!(p["hashline"]["anchor"], "line+hash");
+}
